// Local-only persistence. No network request is made when a participant adds a fabric.
let fabricDbPromise;
function fabricDB(){if(!fabricDbPromise)fabricDbPromise=new Promise((resolve,reject)=>{const req=indexedDB.open('feeling-fabric-local-v3',1);req.onupgradeneeded=()=>req.result.createObjectStore('works',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});return fabricDbPromise}
async function readStoredWorks(){const db=await fabricDB();return new Promise((resolve,reject)=>{const req=db.transaction('works','readonly').objectStore('works').getAll();req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function putStoredWork(work){const db=await fabricDB();return new Promise((resolve,reject)=>{const tx=db.transaction('works','readwrite');tx.objectStore('works').put(work);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
