// The artist's original layer data and the visitor's fabric share one renderer.
var artistToolsReady=false;
const maxFabricLayers=12;
let editedCutout=-1,selectedDecoration=0,constructionDrag=null;
function studyComposition(study){
 const original=structuredClone(study.composition);
 return {...original,version:3,renderer:'felt-lite-v1',artistStudy:study.id,baseShape:'none',baseColor:'#ece3d2',canvasColor:'#f1eadd',strokes:[],title:'',note:'',layers:original.layers.map((l,i)=>migrateFeltLayer({...l,fibreRecipe:artistMaterialSeeds[study.id][i]}))};
}
for(const study of artistStudies){const option=document.createElement('option');option.value=study.id;option.textContent=String(study.id).padStart(2,'0')+' · '+study.label;$('artist-study').append(option)}
function describeStudy(){const study=artistStudies.find(s=>s.id===+$('artist-study').value);$('artist-study-description').textContent=study.label+' · '+study.composition.layers.length+' editable pieces.'}
$('artist-study').onchange=describeStudy;describeStudy();
$('load-study').onclick=()=>{remember();const study=artistStudies.find(s=>s.id===+$('artist-study').value);state=studyComposition(study);selected=0;editedCutout=-1;selectedDecoration=0;editingShape=false;record=null;saveKey=crypto.randomUUID();$('seam-mode').value='move';sync();toast('Study '+String(study.id).padStart(2,'0')+' opened as editable pieces. Your three words are unchanged.')};
for(const study of artistStudies)for(const [i,layer] of study.composition.layers.entries()){
 const option=document.createElement('option');option.value=study.id+':'+i;option.textContent=String(study.id).padStart(2,'0')+' · '+study.label+' / piece '+(i+1);$('cut-pattern').append(option);
}
$('apply-cut').onclick=()=>{const l=state.layers[selected];if(l.component==='button')return;remember();const [id,index]=$('cut-pattern').value.split(':').map(Number),pattern=artistStudies.find(s=>s.id===id).composition.layers[index];for(const key of ['shape','silhouette','cutouts','contour','edge','lobes','fringeEnd','fringeDirection','fringeWidth']){if(pattern[key]===undefined)delete l[key];else l[key]=structuredClone(pattern[key])}editedCutout=-1;sync()};
function syncConstruction(){
 const l=state.layers[selected],holes=l.cutouts||[],details=l.decorations||[];
 if(editedCutout>=holes.length)editedCutout=-1;
 $('cutout-select').replaceChildren();for(let i=-1;i<holes.length;i++){const o=document.createElement('option');o.value=i;o.textContent=i<0?'Outer edge':'Opening '+(i+1);$('cutout-select').append(o)}$('cutout-select').value=editedCutout;
 $('remove-cutout').disabled=editedCutout<0;$('apply-cut').disabled=l.component==='button';
 $('down').disabled=selected===0;$('toggle-layer').textContent=l.visible?'Hide layer':'Show layer';
 selectedDecoration=Math.min(selectedDecoration,Math.max(0,details.length-1));$('decoration-select').replaceChildren();
 if(!details.length){const o=document.createElement('option');o.value='';o.textContent='No placed details';$('decoration-select').append(o)}
 details.forEach((d,i)=>{const o=document.createElement('option');o.value=i;o.textContent=(i+1)+' · '+({tuft:'Thread tuft',button:'Sewn button',buttonhole:'Buttonhole'}[d.kind]||d.kind);$('decoration-select').append(o)});
 $('decoration-select').value=details.length?selectedDecoration:'';$('decoration-controls').hidden=!details.length;
 if(details.length){const d=details[selectedDecoration];$('decoration-x').value=d.x;$('decoration-y').value=d.y;$('decoration-size').value=d.size}
 $('fringe-controls').hidden=l.finish!=='fringe';$('fringe-x').value=l.fringeEnd?.[0]||0;$('fringe-y').value=l.fringeEnd?.[1]||0;$('fringe-width').value=l.fringeWidth||140;const direction=l.fringeDirection||[0,1];$('fringe-angle').value=Math.atan2(direction[1],direction[0])*180/Math.PI;
}
$('cutout-select').onchange=()=>{editedCutout=+$('cutout-select').value;editingShape=true;syncConstruction();render()};
$('remove-cutout').onclick=()=>{if(editedCutout<0)return;remember();state.layers[selected].cutouts.splice(editedCutout,1);editedCutout=-1;sync()};
$('down').onclick=()=>{if(selected===0)return;remember();[state.layers[selected],state.layers[selected-1]]=[state.layers[selected-1],state.layers[selected]];selected--;sync()};
$('toggle-layer').onclick=()=>{remember();state.layers[selected].visible=!state.layers[selected].visible;sync()};
$('decoration-select').onchange=()=>{selectedDecoration=+$('decoration-select').value;syncConstruction()};
for(const [id,key] of [['decoration-x','x'],['decoration-y','y'],['decoration-size','size']])$(id).oninput=()=>{const d=state.layers[selected].decorations[selectedDecoration];if(d){d[key]=+$(id).value;render()}};
$('remove-decoration').onclick=()=>{remember();state.layers[selected].decorations.splice(selectedDecoration,1);sync()};
for(const id of ['fringe-x','fringe-y','fringe-width','fringe-angle'])$(id).oninput=()=>{const l=state.layers[selected];l.fringeEnd=[+$('fringe-x').value,+$('fringe-y').value];l.fringeWidth=+$('fringe-width').value;const t=+$('fringe-angle').value*Math.PI/180;l.fringeDirection=[Math.cos(t),Math.sin(t)];l.fringeAttached=false;render()};
$('finish-style').oninput=()=>{const l=state.layers[selected];l.finish=$('finish-style').value;syncConstruction();render()};
function localCutPoint(p,l){const angle=-l.rotation*Math.PI/180,dx=p.x-l.x,dy=p.y-l.y;return [(dx*Math.cos(angle)-dy*Math.sin(angle))/(l.size*1.2*l.width/100),(dx*Math.sin(angle)+dy*Math.cos(angle))/(l.size*1.4*l.height/100)]}
function customOutline(l,index=selected){if(l.shape==='gesture')return;const phase=rng(state.seed+index*9173)()*6.28;l.silhouette=Array.from({length:96},(_,i)=>outlinePoint(l,i/96*Math.PI*2,phase));l.shape='gesture';l.edge=0;l.contour=[];}
// Direct point handles also edit holes; original studies retain every authored vertex.
const drawLegacyHandles=renderEditor;
renderEditor=function(art){
 const l=state.layers[selected];if(!editingShape||!l?.visible)return;
 if(l.shape!=='gesture')return drawLegacyHandles(art);
 const points=editedCutout<0?l.silhouette:l.cutouts?.[editedCutout];if(!points)return;
 const a=l.size*1.2*l.width/100,b=l.size*1.4*l.height/100,g=el('g',{'data-editor':'true',transform:`translate(${l.x} ${l.y}) rotate(${l.rotation})`},art);
 el('path',{d:'M'+points.map(p=>[p[0]*a,p[1]*b].join(',')).join('L')+'Z',fill:'none',stroke:'#657d50','stroke-width':1.5,'pointer-events':'none'},g);
 points.forEach((p,i)=>{const c=el('circle',{cx:p[0]*a,cy:p[1]*b,r:matchMedia('(pointer: coarse)').matches?7:3.5,fill:'#f9f9ed',stroke:'#657d50','stroke-width':1,'data-cut-point':i,style:'cursor:crosshair'},g);el('title',{},c).textContent='Move cut point '+(i+1)});
};
const constructionModes=['piece','hole','tuft','buttonhole','button','fringe'];
$('art').addEventListener('pointerdown',e=>{
 const handle=e.target.closest('[data-cut-point]'),mode=$('seam-mode').value;
 if(!handle&&!constructionModes.includes(mode))return;
 e.preventDefault();e.stopImmediatePropagation();const l=state.layers[selected];
 if(!handle&&mode==='piece'&&state.layers.length>=maxFabricLayers)return toast('Use up to 12 layers. Remove a piece to add another.');
 if(!handle&&mode!=='piece'&&l.component==='button')return toast('Select a fabric piece first.');
 remember();const p=svgPoint(e);constructionDrag={mode:handle?'point':mode,point:handle?+handle.dataset.cutPoint:null,points:[[p.x,p.y]]};$('art').setPointerCapture(e.pointerId);
 if(['tuft','buttonhole','button'].includes(mode)){
  if((l.decorations||[]).length>=30){constructionDrag=null;return toast('Use up to 30 details per piece.')}
  const [x,y]=localCutPoint(p,l);l.decorations||=[];l.decorations.push({kind:mode,x,y,size:24});selectedDecoration=l.decorations.length-1;sync();
 }
},true);
$('art').addEventListener('pointermove',e=>{
 if(!constructionDrag)return;e.preventDefault();e.stopImmediatePropagation();const p=svgPoint(e),l=state.layers[selected],d=constructionDrag;
 if(d.mode==='point'){const points=editedCutout<0?l.silhouette:l.cutouts[editedCutout];points[d.point]=localCutPoint(p,l);render();return}
 if(['piece','hole','fringe'].includes(d.mode)){const last=d.points.at(-1);if(Math.hypot(p.x-last[0],p.y-last[1])<3)return;d.points.push([p.x,p.y]);let ghost=$('art').querySelector('#cut-ghost');if(!ghost)ghost=el('path',{id:'cut-ghost',fill:d.mode==='fringe'?'none':'#a6c6cf',opacity:.5,stroke:'#526b67','stroke-width':2,'pointer-events':'none'},$('art'));const points=d.mode==='fringe'?[d.points[0],d.points.at(-1)]:d.points;ghost.setAttribute('d','M'+points.map(p=>p.join(' ')).join('L')+(d.mode==='fringe'?'':'Z'))}
},true);
for(const event of ['pointerup','pointercancel'])$('art').addEventListener(event,e=>{
 if(!constructionDrag)return;e.stopImmediatePropagation();const d=constructionDrag,l=state.layers[selected];constructionDrag=null;
 if(event==='pointerup'&&d.points.length>2){
  const points=d.points.length>384?Array.from({length:384},(_,i)=>d.points[Math.floor(i*d.points.length/384)]):d.points;
  if(d.mode==='piece'){
   const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),x=(Math.min(...xs)+Math.max(...xs))/2,y=(Math.min(...ys)+Math.max(...ys))/2;
   state.layers.push(migrateFeltLayer({...structuredClone(baseLayer),id:Date.now(),x,y,size:200,width:125,height:750/7,rotation:0,shape:'gesture',edge:0,contour:[],cutouts:[],silhouette:points.map(p=>[(p[0]-x)/300,(p[1]-y)/300])}));selected=state.layers.length-1;editedCutout=-1;
  }else if(d.mode==='hole'){customOutline(l);l.cutouts||=[];l.cutouts.push(points.map(p=>localCutPoint({x:p[0],y:p[1]},l)));editedCutout=l.cutouts.length-1;
  }else if(d.mode==='fringe'){const a=localCutPoint({x:points[0][0],y:points[0][1]},l),b=localCutPoint({x:points.at(-1)[0],y:points.at(-1)[1]},l),dx=b[0]-a[0],dy=b[1]-a[1],len=Math.hypot(dx,dy)||1;l.finish='fringe';l.fringeEnd=[(a[0]+b[0])/2,(a[1]+b[1])/2];l.fringeDirection=[-dy/len,dx/len];l.fringeWidth=Math.min(250,Math.hypot(dx*l.size*1.2*l.width/100,dy*l.size*1.4*l.height/100));l.fringeAttached=false;}
 }
 if(d.mode!=='point')$('seam-mode').value='move';sync();
},true);

artistToolsReady=true;sync();

// Free colour selection, applied independently to the active layer's four colours.
var colourPickerReady=false;
let colourTarget='color',colourHue=0,colourDragging=false;
function hexToHSV(hex){const [r,g,b]=hex.slice(1).match(/../g).map(v=>parseInt(v,16)/255),v=Math.max(r,g,b),min=Math.min(r,g,b),d=v-min;let h=0;if(d){if(v===r)h=((g-b)/d)%6;else if(v===g)h=(b-r)/d+2;else h=(r-g)/d+4;h=(h*60+360)%360}return {h,s:v?d/v:0,v}}
function hsvToHex(h,s,v){const c=v*s,x=c*(1-Math.abs((h/60)%2-1)),m=v-c,channels=h<60?[c,x,0]:h<120?[x,c,0]:h<180?[0,c,x]:h<240?[0,x,c]:h<300?[x,0,c]:[c,0,x];return '#'+channels.map(n=>Math.round((n+m)*255).toString(16).padStart(2,'0')).join('')}
function syncColourPicker(preserveHue=false){const l=state.layers[selected],hex=l[colourTarget],hsv=hexToHSV(hex);if(!preserveHue&&hsv.s>0)colourHue=hsv.h;$('colour-field').style.setProperty('--picked-hue',`hsl(${colourHue} 100% 50%)`);$('colour-marker').style.left=hsv.s*100+'%';$('colour-marker').style.top=(1-hsv.v)*100+'%';$('colour-field').setAttribute('aria-valuenow',Math.round(hsv.s*100));$('colour-field').setAttribute('aria-valuetext',`Saturation ${Math.round(hsv.s*100)}%, brightness ${Math.round(hsv.v*100)}%`);$('colour-hue').value=Math.round(colourHue);$('colour-native').value=hex;if(document.activeElement!==$('colour-hex'))$('colour-hex').value=hex.toUpperCase();document.querySelectorAll('[data-colour-target]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.colourTarget===colourTarget));b.querySelector('span').style.background=l[b.dataset.colourTarget]})}
function applyPickedColour(hex){state.layers[selected][colourTarget]=hex.toLowerCase();for(const id of ['color','threadColor','secondaryColor','accentColor'])$(id).value=state.layers[selected][id];syncColourPicker(true);layerList();render()}
for(const b of document.querySelectorAll('[data-colour-target]'))b.onclick=()=>{colourTarget=b.dataset.colourTarget;syncColourPicker()};
function pickColourAt(e){const rect=$('colour-field').getBoundingClientRect(),s=Math.max(0,Math.min(1,(e.clientX-rect.left)/rect.width)),v=1-Math.max(0,Math.min(1,(e.clientY-rect.top)/rect.height));applyPickedColour(hsvToHex(colourHue,s,v))}
$('colour-field').onpointerdown=e=>{e.preventDefault();remember();colourDragging=true;$('colour-field').focus();$('colour-field').setPointerCapture(e.pointerId);pickColourAt(e)};
$('colour-field').onpointermove=e=>{if(colourDragging)pickColourAt(e)};
for(const event of ['pointerup','pointercancel'])$('colour-field').addEventListener(event,()=>{colourDragging=false;persistDraft()});
$('colour-field').onkeydown=e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();e.stopPropagation();remember();const hsv=hexToHSV(state.layers[selected][colourTarget]),step=e.shiftKey?.1:.01;if(e.key==='ArrowLeft')hsv.s-=step;if(e.key==='ArrowRight')hsv.s+=step;if(e.key==='ArrowUp')hsv.v+=step;if(e.key==='ArrowDown')hsv.v-=step;applyPickedColour(hsvToHex(colourHue,Math.max(0,Math.min(1,hsv.s)),Math.max(0,Math.min(1,hsv.v))))};
$('colour-hue').oninput=()=>{const hsv=hexToHSV(state.layers[selected][colourTarget]);colourHue=+$('colour-hue').value;applyPickedColour(hsvToHex(colourHue,hsv.s,hsv.v))};
$('colour-native').oninput=()=>{const hex=$('colour-native').value,hsv=hexToHSV(hex);colourHue=hsv.h;applyPickedColour(hex)};
$('colour-hex').oninput=()=>{let hex=$('colour-hex').value.trim();if(!hex.startsWith('#'))hex='#'+hex;if(/^#[0-9a-f]{6}$/i.test(hex)){colourHue=hexToHSV(hex).h;applyPickedColour(hex);$('colour-hex').setCustomValidity('')}else $('colour-hex').setCustomValidity('Enter a six-digit hex colour, for example #A6C6CF.')};
$('colour-hex').onblur=()=>{$('colour-hex').setCustomValidity('');$('colour-hex').value=state.layers[selected][colourTarget].toUpperCase()};
colourPickerReady=true;syncColourPicker();

let atlasMode='cloth';
const atlasNS='http://www.w3.org/2000/svg';let atlasView={x:0,y:0,size:2400},atlasGroup=0,atlasSelection=null,atlasHover=null,atlasPan=null,atlasMoved=false;const atlasCentre=1200,atlasPageSize=24;
function sn(tag,attrs={},parent){const n=document.createElementNS(atlasNS,tag);for(const [k,v] of Object.entries(attrs))n.setAttribute(k,v);if(parent)parent.append(n);return n}
function atlasPositions(data){const pts=data.map(f=>{const theta=(-90+(f.id-1)*137.50776405003785)*Math.PI/180,r=260+(7-f.study.mean)/6*560;return{id:f.id,theta,r,ax:1200+Math.cos(theta)*r,ay:1200+Math.sin(theta)*r,x:1200+Math.cos(theta)*r,y:1200+Math.sin(theta)*r}});for(let step=0;step<220;step++){let moved=false;for(let i=0;i<pts.length;i++)for(let j=i+1;j<pts.length;j++){const a=pts[i],b=pts[j],dx=b.x-a.x,dy=b.y-a.y;if(Math.abs(dx)<135&&Math.abs(dy)<154){const overlapX=135-Math.abs(dx),overlapY=154-Math.abs(dy);if(overlapX<overlapY){const d=(dx>=0?1:-1)*(overlapX/2+.15);a.x-=d;b.x+=d}else{const d=(dy>=0?1:-1)*(overlapY/2+.15);a.y-=d;b.y+=d}moved=true}}if(!moved)break}return pts}
const atlasAnchors=atlasPositions(features);
function sortedWorks(){return [...contributions].sort((a,b)=>a.createdAt.localeCompare(b.createdAt)||a.id.localeCompare(b.id))}
function studyWorkPositions(){const all=sortedWorks(),page=all.slice(atlasGroup*atlasPageSize,(atlasGroup+1)*atlasPageSize);return page.map((w,i)=>{const theta=(-90+i*360/atlasPageSize)*Math.PI/180;return{work:w,x:1200+Math.cos(theta)*1060,y:1200+Math.sin(theta)*1060,index:atlasGroup*atlasPageSize+i}})}
function featurePositions(){return atlasMode==='cloth'?features.map(f=>({id:f.id,...f.clothPosition,ax:f.clothPosition.x,ay:f.clothPosition.y})):atlasAnchors}
function workPositions(){if(atlasMode==='study')return studyWorkPositions();const page=sortedWorks().slice(atlasGroup*atlasPageSize,(atlasGroup+1)*atlasPageSize),h=sourceMeta.clothImage.height;return page.map((work,i)=>({work,index:atlasGroup*atlasPageSize+i,x:100+(i%12)*200,y:i<12?h+150:-150}))}
function mapAspect(){return Math.max(.45,$('map-viewport').clientWidth/Math.max(1,$('map-viewport').clientHeight))}
function updateMapView(){$('collective-map').setAttribute('viewBox',`${atlasView.x} ${atlasView.y} ${atlasView.size} ${atlasView.h||atlasView.size}`)}
function fitMap(){const aspect=mapAspect();if(atlasMode==='cloth'){const n=workPositions().length,top=n>12?-250:-40,bottom=sourceMeta.clothImage.height+(n?250:40),w=Math.max(2480,(bottom-top)*aspect),h=w/aspect;atlasView={x:1200-w/2,y:(top+bottom)/2-h/2,size:w,h}}else{const w=Math.max(2400,2400*aspect),h=w/aspect;atlasView={x:1200-w/2,y:1200-h/2,size:w,h}}updateMapView()}
function zoomMap(factor){const next=Math.max(400,Math.min(6500,atlasView.size*factor)),oldh=atlasView.h||atlasView.size,h=oldh*next/atlasView.size;atlasView.x+=(atlasView.size-next)/2;atlasView.y+=(oldh-h)/2;atlasView.size=next;atlasView.h=h;updateMapView()}
function focusPoint(p,size=1100){const h=size/mapAspect();atlasView={x:p.x-size/2,y:p.y-h/2,size,h};updateMapView()}
function detailText(tag,text,parent,cls){const n=document.createElement(tag);n.textContent=text;if(cls)n.className=cls;parent.append(n);return n}
function relatedWords(ids){return ids.map(id=>features.find(f=>f.id===id)?.label||'Missing '+id)}
function detailWord(id){const f=features.find(f=>f.id===id),box=$('map-detail');box.replaceChildren();detailText('p','ARTIST’S ORIGINAL · '+String(id).padStart(2,'0'),box,'eyebrow');detailText('h3',f.label,box);const im=document.createElement('img');im.src=f.image;im.alt='Artist interpretation of '+f.label;box.append(im);detailText('p',f.interpretation,box);detailText('p','Original-study rating: '+f.study.mean.toFixed(3)+' / 7',box,'data-value');const works=sortedWorks().filter(w=>w.wordIds.includes(id));detailText('h4',works.length+' '+(works.length===1?'selection':'selections')+' in this browser',box);detailText('p','Participation, not an importance score.',box,'muted');for(const w of works){const b=document.createElement('button');b.className='related-work';const image=artworkImage(w.svg,w.title);b.append(image,document.createTextNode(w.title));b.onclick=()=>selectWork(w.id,true);box.append(b)}if(!works.length)detailText('p','No participant fabrics yet. Yours could be the first.',box)}
function detailWork(id){const w=contributions.find(x=>x.id===id);if(!w)return;const box=$('map-detail');box.replaceChildren();detailText('p','PARTICIPANT FABRIC',box,'eyebrow');detailText('h3',w.title,box);box.append(artworkImage(w.svg,w.title));const list=document.createElement('div');list.className='selected-strip';relatedWords(w.wordIds).forEach(t=>detailText('span',t,list,'tag'));box.append(list);if(w.note)detailText('p',w.note,box);detailText('p','Saved '+new Date(w.createdAt).toLocaleString('en-US')+' · this browser only',box,'muted');const b=document.createElement('button');b.textContent='Download this fabric ↓';b.onclick=()=>{const previous=record;record=w;exportWork('png');record=previous};box.append(b);const wear=document.createElement('button');wear.textContent='See it on clothing ↗';wear.className='primary';wear.onclick=()=>openGarment(w,'archive');box.append(wear)}
function selectWord(id){atlasHover=null;atlasSelection={type:'word',id};drawAtlas();detailWord(id);$('collective-map').querySelector('[data-feature-id="'+id+'"]')?.focus({preventScroll:true})}
